import json,copy
from pathlib import Path
from content_helper import case,rows
rows.clear()
case('P255','A_01560',['把薄荷叶按入玻璃杯','观察手指按叶、另一手扶杯及低位操作协调。','叶片应在手指作用下接触杯口或杯内食材，玻璃杯应由砧板承托。','柔软叶片可弯曲、压缩或进入杯中，不要求立刻碎成汁液。','若松手，观察叶片回弹或保留位置及杯体稳定。','只有摆放叶片准备，实际按入不足以评价时选择无法判断。','手指按压、薄荷叶弯曲与杯内支撑'],['Press mint leaves into a glass','Consider finger pressure, other-hand glass stabilization, and low-level coordination.','Leaves should contact the rim or contents through finger action, with the glass supported by the board.','Soft leaves may bend, compress, or enter the glass. Immediate crushing into juice is not required.','On release, consider rebound or retention and glass stability.','Choose unable to judge if only leaf setup is shown and actual pressing cannot be assessed.','Finger pressure, mint-leaf bending, and glass-interior support'])
old=json.loads(Path(__file__).with_name('batch_30.json').read_text());c=copy.deepcopy(next(x for x in old if x['sample_id']=='P250'));c.update(sample_id='P256',media_id='A_01095',shared_task_basis='与P250同为砧板上菜刀切葱，细长叶茎弯曲与分段作用条件相同');rows.append(c)
case('P257','A_01074',['用菜刀切紫胡萝卜','观察持刀与扶持细长根茎的双手协调。','刀刃作用应对应根茎切口，砧板与扶持应合理限制滚动。','根茎可形成片块，截面颜色按可见内容评价，不要求像叶菜一样柔软折叠。','若片块分离或滚动，观察重力与砧板接触。','只有放刀准备，实际刀与根茎作用不足以评价时选择无法判断。','双手控刀、紫胡萝卜分离与砧板限制'],['Cut a purple carrot with a kitchen knife','Consider coordinated knife control and stabilization of the slender root.','Blade action should correspond to cuts, with board and hand plausibly limiting rolling.','Root slices or pieces may form. Assess visible interior color without requiring leafy flexibility.','If pieces separate or roll, consider gravity and board contact.','Choose unable to judge if only setup is shown and actual knife–root action cannot be assessed.','Knife coordination, purple-carrot separation, and board restraint'])
case('P258','A_00879',['在碗上方刨削橙色食材','观察一手控刨、另一手握料往复摩擦的配合。','食材与金属刨面的作用应相关，刨具与碗的相对位置应合理。','表面可逐渐去除并形成屑丝，不推断橙色食材的具体品种，也不要求大块断裂。','若碎屑落下，观察重力和入碗位置，不要求每一小屑清晰可见。','实际刨削接触无法辨认时选择无法判断。','双手刨削、表面去除与碗内收集'],['Grate an orange ingredient above a bowl','Consider grater control and reciprocating ingredient motion with the other hand.','Ingredient action on the metal surface should correspond to abrasion, with plausible grater–bowl placement.','Surface material may gradually become shreds. Do not infer the exact ingredient or require large fractures.','If shreds fall, consider gravity and bowl entry without requiring each tiny particle to be resolved.','Choose unable to judge if actual grating contact cannot be distinguished.','Two-hand grating, surface removal, and bowl collection'])
case('P259','A_00417',['在砧板上把黄瓜切成片','观察持刀下切与扶黄瓜手逐渐后移的协调。','刀刃、黄瓜和砧板接触应连续，新切片应与刀作用对应。','剩余黄瓜可保持圆柱形并逐步缩短，不把已有切片当作当前切割完成。','若片块倾倒、滑开或刀抬起，观察支撑和重力。','只有持刀准备，实际切片过程不足以评价时选择无法判断。','双手控刀扶瓜、黄瓜成片与砧板接触'],['Slice a cucumber on a board','Consider downward cutting and coordinated withdrawal of the stabilizing hand.','Blade, cucumber, and board contact should remain continuous, with new slices related to blade action.','The remaining cylinder may shorten gradually. Existing slices do not establish current cutting completion.','If slices topple, slide, or the knife lifts, consider support and gravity.','Choose unable to judge if only preparation is shown and actual slicing cannot be assessed.','Knife–cucumber coordination, slice formation, and board contact'])
case('P260','A_00378',['用小刀切番茄','观察握刀、扶持圆形番茄和控制滚动的双手配合。','刀刃与外皮、软果肉及砧板作用应相关。','番茄可局部压缩、切开或出少量汁液，不要求硬脆断裂或大量喷汁。','若片块分离，观察软组织形变与砧板支撑。','只有刀贴近番茄，实际切入不足以评价时选择无法判断。','双手控刀、番茄软组织分离与砧板支撑'],['Cut a tomato with a small knife','Consider grip, round-fruit stabilization, and control of rolling.','Blade action should relate to skin, soft flesh, and board contact.','The tomato may compress, open, or release a little juice. Brittle fracture or abundant spray is not required.','If pieces separate, consider soft-tissue deformation and board support.','Choose unable to judge if only blade positioning is shown and actual entry cannot be assessed.','Knife coordination, soft-tomato separation, and board support'])
case('P261','A_00159',['用小刀切带叶胡萝卜','观察持刀、扶根茎与手指调整的协调。','刀刃进入根茎应与手部切动对应，叶簇和根体的连接按实际切位评价。','根体可形成片块，不要求叶子必须脱落或胡萝卜全部切完。','若片块滚动或刀退出，观察砧板承托及根茎剩余部分的连续性。','实际切入被遮挡或只有准备时选择无法判断。','双手控刀、胡萝卜根体分离与叶根连续性'],['Cut a leafy carrot with a small knife','Consider knife control, root stabilization, and finger adjustments.','Blade entry should correspond to hand action, with leaf–root connections assessed at the actual cutting location.','Root pieces may form. Leaf detachment or finishing the whole carrot is not required.','On rolling pieces or withdrawal, consider board support and continuity of the remaining root.','Choose unable to judge if entry is obscured or only preparation is shown.','Knife coordination, carrot-root separation, and leaf–root continuity'])
case('P262','A_00065',['用宽刀切玉米棒','观察双手持刀扶玉米与上身下压的配合。','刀刃作用应与玉米棒接触位置相关，砧板应合理承托并限制滚动。','玉米可在受力处切开、压入或掉少量颗粒，不要求像松散谷粒一样整体流动。','若段块或玉米粒分离，观察重力、板面碰撞及剩余棒体支撑。','只有摆刀或切位准备，实际刀玉米作用不足以评价时选择无法判断。','人体下压、玉米棒切入与砧板支撑'],['Cut a corn cob with a broad knife','Consider knife control, cob stabilization, and upper-body downward pressure.','Blade action should correspond to cob contact, with the board supporting and limiting rolling.','The cob may cut, indent, or shed some kernels. Whole-cob granular flow is not required.','If sections or kernels separate, consider gravity, board collision, and support of the remainder.','Choose unable to judge if only knife placement is shown and actual action cannot be assessed.','Body pressure, corn-cob cutting, and board support'])
case('P263','A_02277',['用削皮工具去除黄瓜表皮','观察一手扶瓜、另一手沿表面移动工具的协调。','刃口与表皮接触和削皮方向应相关，不能按切厚片的唯一方式评价。','薄皮可卷曲或脱离并露出较浅表面，不要求黄瓜整体断成两段。','若皮条落下或工具离开，观察柔性、重力和瓜体支撑。','刃口实际作用不足以评价或只有展示工具时选择无法判断。','双手削皮、黄瓜表面去除与皮条运动'],['Remove cucumber skin with a peeling tool','Consider cucumber stabilization and coordinated surface strokes.','Blade contact and peeling direction should correspond without requiring thick-slice cutting.','Thin skin may curl or detach, exposing a lighter surface. Halving the whole cucumber is not required.','If peel falls or the tool withdraws, consider flexibility, gravity, and cucumber support.','Choose unable to judge if actual blade action cannot be assessed or only the tool is displayed.','Two-hand peeling, cucumber-surface removal, and peel motion'])
case('P264','A_01458',['用压泥器压碎碗内熟土豆','观察握柄下压、扶碗与上身配合。','压头、土豆块和碗底接触应与按压对应。','熟土豆可压扁、分裂或逐渐成为泥状，不要求一次完全均匀。','若压头抬起，观察食材黏附或回落及玻璃碗支撑，不要求碗体变形。','只有工具放在碗内，实际按压不足以评价时选择无法判断。','人体下压、熟土豆压碎与玻璃碗承托'],['Mash cooked potatoes in a bowl','Consider handle pressure, bowl stabilization, and upper-body coordination.','Masher, potato chunks, and bowl-bottom contact should correspond to pressing.','Cooked potatoes may flatten, fragment, or gradually mash. Immediate uniformity is not required.','On lifting, consider adhesion or falling food and glass-bowl support without requiring bowl deformation.','Choose unable to judge if the tool merely rests in the bowl and actual pressing cannot be assessed.','Body pressure, cooked-potato crushing, and glass-bowl support'])
case('P265','A_01381',['用削皮刀去除土豆外皮','观察持刀、扶持圆形土豆和调节切向的双手配合。','刃口应沿外表面作用，土豆应由手或砧板合理承托。','粗糙外皮可被削去，露出内部表面，不要求整个土豆被切块。','若皮屑分离或土豆转动，观察重力、连续外形及手部固定。','只有刀位准备，实际表面去除不足以评价时选择无法判断。','双手削皮、土豆外皮分离与根体承托'],['Peel a potato with a peeling knife','Consider knife control, round-potato stabilization, and changing stroke orientation.','The blade should act along the outer surface, with hand or board support.','Rough skin may separate and expose inner tissue. Dicing the whole potato is not required.','On peel separation or potato rotation, consider gravity, continuous form, and stabilization.','Choose unable to judge if only blade setup is shown and actual surface removal cannot be assessed.','Two-hand peeling, potato-skin separation, and root support'])
case('P266','A_01355',['把切好的洋葱放入锅中','观察手部收拢碎块、承托转移和释放的协调。','洋葱块应从砧板经手或可见工具移向锅口，不能只按已有锅内内容判断。','碎块可单独或成组掉落，不要求形成液体流。','若入锅或留在板上，观察重力、锅沿碰撞和支撑转换，不要求全部转移完。','只有伸手准备或实际移料被遮挡时选择无法判断。','手部转移、洋葱块释放与锅板支撑转换'],['Transfer chopped onion into a pot','Consider gathering pieces, supporting transfer, and release.','Pieces should move from board via hand or visible tool toward the pot. Existing pot contents alone do not establish transfer.','Pieces may fall separately or in groups without liquid-like flow.','On pot entry or retention on the board, consider gravity, rim collision, and support transfer without requiring complete emptying.','Choose unable to judge if only reaching preparation is shown or actual transfer is obscured.','Hand transfer, onion-piece release, and pot–board support transitions'])
case('P267','A_00370',['拉开汽车后备箱盖','观察手部操作锁扣、抬盖与身体平衡。','箱盖应围绕合理铰接转动，手与盖缘或锁扣的作用应连续。','箱盖可以部分开启，不要求车体移动或箱盖变形。','若手松开或盖停止，观察铰链支撑及可见保持，不推断隐藏助力装置结构。','只有摸索锁扣，实际开启不足以评价时选择无法判断。','手部抬盖、后备箱铰接与车体支撑'],['Pull open a car trunk lid','Consider latch operation, lid lifting, and body balance.','The lid should rotate around plausible hinges with continuous hand action at the edge or latch.','Partial opening is sufficient. Car movement or lid deformation is not required.','On release or stopping, consider hinge support and retention without inferring hidden assist structure.','Choose unable to judge if only latch preparation is shown and actual opening cannot be assessed.','Hand lifting, trunk-lid hinging, and vehicle support'])
case('P268','A_04110',['按压调整汽车尾翼的位置','观察双手压持、手臂导向与上身平衡。','尾翼与支架或安装面接触应相关，手部按压应对应调整。','尾翼可对齐或就位，不要求金属永久变形或后备箱同时关闭。','若松手，观察可见连接与支撑，不推断隐藏紧固件已安装。','只有指示位置，实际压调不足以评价时选择无法判断。','双手压调、尾翼安装连接与车体支撑'],['Press and align a car rear spoiler','Consider two-hand pressure, arm guidance, and balance.','Spoiler contact with brackets or mounting surfaces should correspond to adjustment.','The spoiler may align or seat. Permanent metal deformation or simultaneous trunk closing is not required.','On release, consider visible connection and support without inferring hidden fasteners.','Choose unable to judge if only pointing is shown and actual pressing cannot be assessed.','Two-hand adjustment, spoiler mounting connections, and vehicle support'])
case('P269','A_01694',['把金属桶推入汽车后部','观察双手承托、推移或转正大桶与身体承力协调。','桶与手、车厢底部和开口接触应连续，运动方向应与施力相容。','刚性桶可平移或转动，不要求桶壁明显压扁。','若桶就位或松手，观察重力、滚动限制与车内支撑，不凭外观推断精确重量。','只有扶桶准备，实际移动不足以评价时选择无法判断。','人体推移承重、桶体运动与车厢接触支撑'],['Push a metal barrel into the rear of a vehicle','Consider two-hand support, pushing or reorientation, and load-related body coordination.','Barrel contact with hands, cargo floor, and opening should remain continuous, with motion compatible with applied action.','The rigid barrel may translate or rotate without visible wall crushing.','On placement or release, consider gravity, rolling limits, and interior support without inferring exact weight from appearance.','Choose unable to judge if only preparation is shown and actual movement cannot be assessed.','Body pushing and load support, barrel motion, and vehicle contact'])
case('P270','A_02752',['借助勺子向玻璃杯倒饮料','观察一手倾罐、另一手定位勺面和双手协调。','罐口、勺面与杯口的液体路径应相关，杯应得到桌面承托。','液体可沿勺分流并与已有饮料泡沫接触，不要求完全没有泡沫或固定分层。','若停倒或泡沫变化，观察流束中断、重力与杯内液位，不要求倒完整罐。','只有对位准备，实际流动不足以评价时选择无法判断。','双手倾罐控勺、液体路径与杯内积聚'],['Pour a drink into a glass using a spoon','Consider can tilting, spoon positioning, and two-hand coordination.','Flow from can opening through spoon toward the glass should correspond, with table support for the glass.','Liquid may spread over the spoon and contact existing drink and foam. No-foam pouring or a fixed layer pattern is not required.','On stopping or foam changes, consider flow interruption, gravity, and liquid level without requiring an empty can.','Choose unable to judge if only alignment is shown and actual flow cannot be assessed.','Can–spoon coordination, liquid path, and glass accumulation'])
Path(__file__).with_name('batch_31.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
